//! ZIP32 reader and byte-range manifest. Original archive remains immutable in Session.
use crate::{Error,MAX_INPUT,deflate::inflate};
use std::{collections::HashSet,ops::Range};
pub const MAX_ARCHIVE:usize=60*1024*1024;
const MAX_ENTRIES:usize=2000;
pub const SLOT:&str="Saves/save_0.save";
pub const ACCOUNT:&str="SettingsAccount/settings.json";
#[derive(Debug,Clone,PartialEq,Eq)]pub struct Entry{pub name:String,pub method:u16,pub flags:u16,pub crc:u32,pub size:usize,pub local:Range<usize>,pub compressed:Range<usize>,pub central:Range<usize>}
#[derive(Debug)]pub struct ZipIndex{pub entries:Vec<Entry>,pub central:Range<usize>,pub eocd:Range<usize>}
fn take(b:&[u8],p:usize,n:usize)->Result<&[u8],Error>{b.get(p..p.checked_add(n).ok_or(Error::Overflow)?).ok_or(Error::Truncated)}
fn u16(b:&[u8],p:usize)->Result<u16,Error>{Ok(u16::from_le_bytes(take(b,p,2)?.try_into().unwrap()))}
fn u32(b:&[u8],p:usize)->Result<u32,Error>{Ok(u32::from_le_bytes(take(b,p,4)?.try_into().unwrap()))}
fn z32(b:&[u8],p:usize)->Result<usize,Error>{let v=u32(b,p)?;if v==u32::MAX{return Err(Error::Schema)}Ok(v as usize)}
fn extra(b:&[u8])->Result<(),Error>{let mut p=0;while p<b.len(){let tag=u16(b,p)?;let n=u16(b,p+2)? as usize;if tag==1{return Err(Error::Schema)}take(b,p+4,n)?;p+=4+n;}Ok(())}
fn name(s:&[u8])->Result<&str,Error>{let n=std::str::from_utf8(s).map_err(|_|Error::Schema)?;if n.is_empty()||n.len()>4096||n.starts_with('/')||n.starts_with('\u{feff}')||n.contains('\\')||n.contains(':')||n.chars().any(|c|c.is_control())||n.strip_suffix('/').unwrap_or(n).split('/').any(|x|x.is_empty()||x=="."||x==".."){return Err(Error::Schema)}Ok(n)}
const fn crc_table()->[u32;256]{let mut t=[0;256];let mut i=0;while i<256{let mut c=i as u32;let mut j=0;while j<8{c=(c>>1)^((0u32.wrapping_sub(c&1))&0xedb88320);j+=1;}t[i]=c;i+=1;}t}
const CRC:[u32;256]=crc_table();
pub fn crc32(bytes:&[u8])->u32{let mut c=0xffff_ffffu32;for &b in bytes{c=(c>>8)^CRC[((c^b as u32)&255)as usize];}!c}
impl ZipIndex{
 pub fn parse(b:&[u8])->Result<Self,Error>{if b.len()>MAX_ARCHIVE||b.len()<22{return Err(Error::Budget)}let mut end=None;for i in (b.len().saturating_sub(22+65535)..=b.len()-22).rev(){if u32(b,i)?==0x06054b50&&i+22+u16(b,i+20)? as usize==b.len(){end=Some(i);break}}let end=end.ok_or(Error::Schema)?;if u16(b,end+4)?!=0||u16(b,end+6)?!=0{return Err(Error::Schema)}let count=u16(b,end+10)? as usize;if count==0||count>MAX_ENTRIES||u16(b,end+8)? as usize!=count{return Err(Error::Budget)}let start=z32(b,end+16)?;let size=z32(b,end+12)?;if start.checked_add(size)!=Some(end){return Err(Error::Schema)}let mut p=start;let mut total=0usize;let mut names=HashSet::new();let mut entries=Vec::with_capacity(count);for _ in 0..count{if u32(b,p)?!=0x02014b50{return Err(Error::Schema)}take(b,p,46)?;let flags=u16(b,p+8)?;let method=u16(b,p+10)?;if flags&!0x0808!=0||!matches!(method,0|8)||u16(b,p+34)?!=0{return Err(Error::Schema)}let crc=u32(b,p+16)?;let comp=z32(b,p+20)?;let size=z32(b,p+24)?;if size>MAX_INPUT||comp>MAX_ARCHIVE||method==0&&size!=comp{return Err(Error::Budget)}total=total.checked_add(size).ok_or(Error::Overflow)?;if total>MAX_ARCHIVE{return Err(Error::Budget)}let nl=u16(b,p+28)? as usize;let xl=u16(b,p+30)? as usize;let cl=u16(b,p+32)? as usize;let lp=z32(b,p+42)?;let np=p+46;let nm=take(b,np,nl)?;let n=name(nm)?.to_owned();if !names.insert(n.clone()){return Err(Error::Duplicate)}extra(take(b,np+nl,xl)?)?;let ce=np+nl+xl+cl;if ce>end{return Err(Error::Truncated)}let ext=u32(b,p+38)?;if ext>>28==0xa{return Err(Error::Schema)}if n.ends_with('/')&&(size!=0||comp!=0){return Err(Error::Schema)}if lp>=start||lp+30>start||u32(b,lp)?!=0x04034b50||u16(b,lp+6)?!=flags||u16(b,lp+8)?!=method{return Err(Error::Schema)}let ln=u16(b,lp+26)? as usize;let lx=u16(b,lp+28)? as usize;if ln!=nl||take(b,lp+30,ln)?!=nm{return Err(Error::Schema)}extra(take(b,lp+30+ln,lx)?)?;let begin=lp+30+ln+lx;let stop=begin.checked_add(comp).ok_or(Error::Overflow)?;if stop>start{return Err(Error::Truncated)}let mut le=stop;if flags&8==0{if u32(b,lp+14)?!=crc||z32(b,lp+18)?!=comp||z32(b,lp+22)?!=size{return Err(Error::Schema)}}else{let local_crc=u32(b,lp+14)?;let local_comp=z32(b,lp+18)?;let local_size=z32(b,lp+22)?;if (local_crc!=0&&local_crc!=crc)||(local_comp!=0&&local_comp!=comp)||(local_size!=0&&local_size!=size){return Err(Error::Schema)}// Both optional-signature and unsigned descriptor forms; reject ambiguity.
 let valid=|q:usize|->bool{q.checked_add(12).is_some_and(|e|e<=start)&&u32(b,q)==Ok(crc)&&z32(b,q+4)==Ok(comp)&&z32(b,q+8)==Ok(size)};let unsigned=valid(stop);let signed=u32(b,stop)==Ok(0x08074b50)&&valid(stop+4);if unsigned==signed{return Err(Error::Schema)}le=stop+if signed{16}else{12};}
 entries.push(Entry{name:n,method,flags,crc,size,local:lp..le,compressed:begin..stop,central:p..ce});p=ce;}
 if p!=end{return Err(Error::Trailing)}let mut ranges:Vec<_>=entries.iter().map(|e|e.local.clone()).collect();ranges.sort_by_key(|r|r.start);if ranges.windows(2).any(|a|a[0].end>a[1].start){return Err(Error::Duplicate)}Ok(Self{entries,central:start..end,eocd:end..b.len()})}
 pub fn extract(&self,raw:&[u8],index:usize)->Result<Vec<u8>,Error>{let e=self.entries.get(index).ok_or(Error::Schema)?;let b=raw.get(e.compressed.clone()).ok_or(Error::Truncated)?;let out=if e.method==0{b.to_vec()}else{inflate(b,e.size)?};if out.len()!=e.size||crc32(&out)!=e.crc{return Err(Error::LengthMismatch)}Ok(out)}
 /// Validate every member, keeping only the two supported files. No untrusted extraction to disk.
 pub fn targets(&self,raw:&[u8])->Result<(Option<Vec<u8>>,Option<Vec<u8>>),Error>{let mut slot=None;let mut account=None;for (i,e) in self.entries.iter().enumerate(){let out=self.extract(raw,i)?;match e.name.as_str(){SLOT=>slot=Some(out),ACCOUNT=>account=Some(out),_=>{}}}if slot.is_none()&&account.is_none(){return Err(Error::Schema)}Ok((slot,account))}
}
